-- ===========================================================================
-- Seed 29 : quizzes for the Rust course
--
-- One per level. Like the other courses without a runner there is no
-- scratchpad on these pages: the playground cannot run Rust, and an HTML
-- scratchpad under a Rust question would be worse than none.
-- starter_for_course() in the website returns null for this course.
--
-- Generated by scratchpad/gen/build_batch5.py, which also checks that every
-- single_choice has exactly one correct option and every multiple_choice has
-- at least two. A quiz that cannot be passed is not obvious from the SQL.
-- ===========================================================================

INSERT INTO assessment_quizzes
  (id, course_id, lesson_id, title, description, pass_percent, time_limit_seconds,
   max_attempts, shuffle_questions, shuffle_options, show_answers, status)
VALUES
  ('f0000001-0000-4000-8000-000000000030',
   'c0000001-0000-4000-8000-00000000000f', 'e0000001-0000-4000-8000-0000000000cd',
   'Level 1 Check: Ownership, Borrowing and Iterators',
   'Moves, the borrowing rule, and what makes an iterator run. Every one of these can be settled by asking the compiler.',
   60, 600, NULL, 0, 1, 1, 'published'),

  ('f0000001-0000-4000-8000-000000000031',
   'c0000001-0000-4000-8000-00000000000f', 'e0000001-0000-4000-8000-0000000000ce',
   'Level 2 Check: Traits, Enums and Results',
   'Static against dynamic dispatch, exhaustive match, and the ? operator.',
   60, 720, NULL, 0, 1, 1, 'published'),

  ('f0000001-0000-4000-8000-000000000032',
   'c0000001-0000-4000-8000-00000000000f', 'e0000001-0000-4000-8000-0000000000cf',
   'Level 3 Check: Lifetimes, Smart Pointers and Threads',
   'What a lifetime annotation says, when to reach for Rc or RefCell, and why Send and Sync exist.',
   70, 720, NULL, 0, 1, 1, 'published'),

  ('f0000001-0000-4000-8000-000000000033',
   'c0000001-0000-4000-8000-00000000000f', 'e0000001-0000-4000-8000-0000000000d0',
   'Expert Exam: Rust',
   'Drop order, zero-cost abstractions, release builds, and how a crate is arranged.',
   70, 1500, 3, 1, 1, 1, 'published')
ON DUPLICATE KEY UPDATE
  title = VALUES(title), description = VALUES(description),
  pass_percent = VALUES(pass_percent), status = VALUES(status);

INSERT INTO assessment_questions
  (id, quiz_id, kind, prompt, explanation, points, `position`, correct_text)
VALUES
  -- Level 1 Check: Ownership, Borrowing and Iterators
  ('a1000001-0000-4000-8000-0000000002e5', 'f0000001-0000-4000-8000-000000000030', 'single_choice',
   '`let a = String::from("x"); let b = a;` - what happens to `a`?',
   'It is moved: `a` is no longer usable, and touching it is a compile error, not a crash. That is what makes a double free impossible. `a.clone()` is the explicit copy, and a type that is `Copy` - an integer, a bool, a char - duplicates instead of moving.',
   2, 1, NULL),

  ('a1000001-0000-4000-8000-0000000002e6', 'f0000001-0000-4000-8000-000000000030', 'single_choice',
   'What is the borrowing rule the compiler enforces?',
   'Either one mutable reference, or any number of immutable ones - never both at the same time. That single rule is what makes data races impossible at compile time, and it is the reason Rust can be concurrent without a garbage collector.',
   3, 2, NULL),

  ('a1000001-0000-4000-8000-0000000002e7', 'f0000001-0000-4000-8000-000000000030', 'multiple_choice',
   'Which are true of `&str` and `String`? Select all that apply.',
   'A String owns a growable heap buffer; a &str is a borrowed view into one, or into a literal in the binary. Taking &str in a parameter accepts both, because String dereferences to &str. And indexing a string by byte is forbidden, because a UTF-8 boundary is not every byte - you iterate by char or slice on a boundary.',
   3, 3, NULL),

  ('a1000001-0000-4000-8000-0000000002e8', 'f0000001-0000-4000-8000-000000000030', 'single_choice',
   'What is the difference between `for x in &v` and `for x in v`?',
   'The first borrows - `v` is still usable afterwards. The second is `into_iter()`: it consumes the vector and moves each element out, so `v` is gone. That single `&` is the difference between reading a collection and giving it away, and it is worth reading carefully every time.',
   2, 4, NULL),

  ('a1000001-0000-4000-8000-0000000002e9', 'f0000001-0000-4000-8000-000000000030', 'true_false',
   '`v.iter().map(|x| expensive(x))` runs `expensive` as soon as the line executes.',
   'False. Iterators are lazy: map builds an adaptor and runs nothing. The work happens when something consumes it - `collect`, `sum`, a `for` loop. That is what lets `.take(3)` on a long chain stop after three, and why an unused iterator chain warns about being unused.',
   2, 5, NULL),

  -- Level 2 Check: Traits, Enums and Results
  ('a1000001-0000-4000-8000-0000000002ea', 'f0000001-0000-4000-8000-000000000031', 'single_choice',
   'What is the difference between `&impl Trait` and `Box<dyn Trait>`?',
   'Static against dynamic dispatch. `impl Trait` monomorphises - one specialised copy per concrete type, resolved at compile time, no allocation and no indirection. `Box<dyn Trait>` is one copy of the code with a vtable lookup per call, and it is what lets a Vec hold several different types. Prefer the first unless you need the second.',
   3, 1, NULL),

  ('a1000001-0000-4000-8000-0000000002eb', 'f0000001-0000-4000-8000-000000000031', 'single_choice',
   'Why must a `match` cover every variant of an enum?',
   'So that adding a variant tells you every place that needs updating. Exhaustiveness turns "I added a state and forgot a branch" from a runtime surprise into a list of compile errors - which is the single most useful property of Rust''s enums, and the reason `_ =>` should be a decision rather than a reflex.',
   3, 2, NULL),

  ('a1000001-0000-4000-8000-0000000002ec', 'f0000001-0000-4000-8000-000000000031', 'single_choice',
   'What does the `?` operator do?',
   'It unwraps an Ok (or Some), or returns the Err (or None) from the enclosing function - converting the error type through `From` on the way. That conversion is the whole ergonomics story: several different error types can flow into one return type with no conversion code written by hand.',
   3, 3, NULL),

  ('a1000001-0000-4000-8000-0000000002ed', 'f0000001-0000-4000-8000-000000000031', 'multiple_choice',
   'Which are good practice for error handling in Rust? Select all that apply.',
   'A library defines an error enum so callers can distinguish failures; an application can use Box<dyn Error> because its caller is a person reading a message. Implementing From lets ? convert automatically. unwrap() turns a compile-time guarantee into a crash - expect("why this cannot fail") at least documents the claim.',
   3, 4, NULL),

  ('a1000001-0000-4000-8000-0000000002ee', 'f0000001-0000-4000-8000-000000000031', 'single_choice',
   'What does `#[derive(PartialEq, Hash)]` give you, and why together?',
   'Both are generated field by field, and they must agree: a HashMap finds an entry by hash and then confirms with equality, so two equal values that hash differently become unfindable. Deriving them together keeps that contract without you writing either.',
   2, 5, NULL),

  -- Level 3 Check: Lifetimes, Smart Pointers and Threads
  ('a1000001-0000-4000-8000-0000000002ef', 'f0000001-0000-4000-8000-000000000032', 'single_choice',
   'What does `fn longest<''a>(x: &''a str, y: &''a str) -> &''a str` promise?',
   'That the returned reference is valid for as long as BOTH inputs are - in practice, the shorter of the two. The annotation does not change any lifetime; it states a relationship the compiler cannot infer with two input references, so it can check the callers.',
   3, 1, NULL),

  ('a1000001-0000-4000-8000-0000000002f0', 'f0000001-0000-4000-8000-000000000032', 'single_choice',
   'When is `RefCell<T>` the right tool?',
   'When you genuinely need to mutate through a shared reference - a cache inside an otherwise immutable object, a counter in a callback. It moves the borrow check to runtime, so breaking the rule panics instead of failing to compile. Reaching for it to get around the borrow checker converts a compile error into a crash your users find.',
   3, 2, NULL),

  ('a1000001-0000-4000-8000-0000000002f1', 'f0000001-0000-4000-8000-000000000032', 'multiple_choice',
   'Which statements about Rc and Arc are true? Select all that apply.',
   'Rc counts with a plain integer and is single-threaded; Arc counts atomically and is Send + Sync, which is why the compiler rejects Rc across a thread boundary before you can run it. Both give shared ownership but not shared mutation - that needs RefCell or Mutex inside. And two Rcs pointing at each other never reach zero, which is how a Rust program leaks.',
   3, 3, NULL),

  ('a1000001-0000-4000-8000-0000000002f2', 'f0000001-0000-4000-8000-000000000032', 'single_choice',
   'What do the `Send` and `Sync` traits mean?',
   'Send means the type can be moved to another thread; Sync means &T can be shared between threads. They are auto-derived, and the types that are neither - Rc, RefCell - are exactly the ones a second thread would corrupt. That is how Rust rejects a data race at compile time rather than finding it in production.',
   3, 4, NULL),

  ('a1000001-0000-4000-8000-0000000002f3', 'f0000001-0000-4000-8000-000000000032', 'true_false',
   'An `mpsc` channel''s receive loop ends when you drop one of the senders.',
   'False. It ends when the LAST sender is dropped. Clone a sender per thread and the original still counts - which is why you drop the original explicitly, or the `for received in rx` loop waits forever for a sender that will never send.',
   2, 5, NULL),

  -- Expert Exam: Rust
  ('a1000001-0000-4000-8000-0000000002f4', 'f0000001-0000-4000-8000-000000000033', 'single_choice',
   'When is a value''s memory released in Rust?',
   'When its owner goes out of scope, at a point the compiler determines. Drop runs then - in reverse declaration order, and while unwinding from a panic too. There is no collector deciding when, which is what makes the cost predictable and why Rust needs no `finally`.',
   3, 1, NULL),

  ('a1000001-0000-4000-8000-0000000002f5', 'f0000001-0000-4000-8000-000000000033', 'single_choice',
   'Your Rust program is far slower than you expected. What do you check first?',
   'Whether it is a release build. A debug build has no optimisation and checks integer overflow on every operation; release builds are routinely ten to fifty times faster. No other single factor comes close, and it is the reason `cargo run` timings should never be quoted.',
   3, 2, NULL),

  ('a1000001-0000-4000-8000-0000000002f6', 'f0000001-0000-4000-8000-000000000033', 'single_choice',
   'What does "zero-cost abstraction" mean in Rust?',
   'That the abstraction has no runtime representation: an iterator chain compiles to the same machine code as the equivalent loop, and a generic function is monomorphised into a specialised copy per type. You pay in compile time and binary size, not in speed - so the readable version is usually also the fast one.',
   3, 3, NULL),

  ('a1000001-0000-4000-8000-0000000002f7', 'f0000001-0000-4000-8000-000000000033', 'single_choice',
   'What does `unsafe` actually turn off?',
   'Nothing - not the borrow checker, not lifetimes, not the type system. It enables five specific operations the compiler cannot verify: dereferencing a raw pointer, calling an unsafe function, implementing an unsafe trait, accessing a mutable static, and reading a union field. The discipline is to keep the block small and wrap it in a safe API.',
   3, 4, NULL),

  ('a1000001-0000-4000-8000-0000000002f8', 'f0000001-0000-4000-8000-000000000033', 'multiple_choice',
   'Which are part of a Rust crate that stays easy to change? Select all that apply.',
   'Items are private unless marked pub, so the public surface is a deliberate decision; pub(crate) marks what is shared internally. A newtype like struct Pence(i64) costs nothing at runtime and makes an argument mix-up a compile error. And doc examples are compiled and run by cargo test, so documentation that goes stale fails the build.',
   3, 5, NULL)
ON DUPLICATE KEY UPDATE
  prompt = VALUES(prompt), explanation = VALUES(explanation),
  points = VALUES(points), `position` = VALUES(`position`);

DELETE FROM assessment_question_options
 WHERE question_id IN (
   SELECT id FROM assessment_questions
    WHERE quiz_id IN ('f0000001-0000-4000-8000-000000000030',
                      'f0000001-0000-4000-8000-000000000031',
                      'f0000001-0000-4000-8000-000000000032',
                      'f0000001-0000-4000-8000-000000000033'));

