  FROM (
    SELECT 'a1000001-0000-4000-8000-0000000002e5' AS question_id, 'a is moved and can no longer be used; using it fails to compile' AS body, 1 AS is_correct, 1 AS pos
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002e5', 'Both a and b point at the same string, like a reference', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002e5', 'a is deep-copied into b, so both are usable', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002e5', 'a becomes an empty string', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002e6', 'Either one &mut, or any number of &, but never both at once', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002e6', 'At most one reference of any kind at a time', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002e6', 'Any number of &mut, as long as they are in different scopes', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002e6', 'References are unrestricted; only ownership is checked', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002e7', 'String owns its buffer; &str borrows a view of one', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002e7', 'A parameter of type &str accepts a String as well as a literal', 1, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002e7', 'Indexing a string by a single byte position does not compile', 1, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002e7', '&str is a null-terminated C string', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002e8', '&v borrows and leaves v usable; v consumes it', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002e8', 'They are identical; the & is optional style', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002e8', '&v is slower because it dereferences each element', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002e8', 'v borrows and &v clones', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002e9', 'True', 0, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002e9', 'False', 1, 2

    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002ea', 'impl Trait is static dispatch; Box<dyn Trait> is dynamic, via a vtable', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002ea', 'impl Trait allocates on the heap and Box does not', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002ea', 'They compile to the same thing; Box is just older syntax', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002ea', 'impl Trait works only for traits with one implementation', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002eb', 'So adding a variant produces a compile error everywhere it is handled', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002eb', 'Because match compiles to a jump table that needs every index', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002eb', 'To let the optimiser remove the bounds check', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002eb', 'It does not have to - the compiler inserts a default arm', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002ec', 'Unwraps Ok, or returns the Err early, converting it through From', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002ec', 'Panics if the value is an Err, like unwrap', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002ec', 'Converts a Result into an Option', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002ec', 'Retries the expression until it succeeds', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002ed', 'A library defines an error enum with Display, Error and From', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002ed', 'An application can return Box<dyn Error> from main', 1, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002ed', 'Prefer expect("why") to unwrap() where you must assert', 1, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002ed', 'unwrap() everywhere, and catch the panic at the top level', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002ee', 'Field-by-field equality and hashing that agree, which HashMap requires', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002ee', 'Reference equality and an address-based hash', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002ee', 'A Debug implementation as a side effect', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002ee', 'Ordering, so the type can be sorted', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002ef', 'The result is valid for as long as the shorter of the two inputs', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002ef', 'Both arguments are given a lifetime of the whole program', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002ef', 'The result is copied, so it outlives both', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002ef', 'x and y must be the same length', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002f0', 'For genuine interior mutability - and it panics if the rule is broken at runtime', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002f0', 'Whenever the borrow checker rejects code, as the standard workaround', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002f0', 'To share data between threads without a mutex', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002f0', 'To avoid cloning large structures', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002f1', 'Rc is single-threaded; Arc uses an atomic count and is thread-safe', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002f1', 'Neither allows mutation on its own - you need RefCell or Mutex inside', 1, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002f1', 'A cycle of Rcs leaks, and Weak is the fix', 1, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002f1', 'Arc::clone deep-copies the value it points at', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002f2', 'Send: movable between threads. Sync: &T shareable between threads', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002f2', 'Send: has a channel. Sync: has a mutex', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002f2', 'Send: can be serialised. Sync: can be cloned', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002f2', 'They mark types the garbage collector may move', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002f3', 'True', 0, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002f3', 'False', 1, 2

    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002f4', 'When its owner goes out of scope, at a compile-time-determined point', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002f4', 'When the garbage collector next runs', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002f4', 'When the reference count reaches zero, for every type', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002f4', 'When you call free() on it', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002f5', 'That it was built with --release', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002f5', 'Whether the garbage collector is tuned correctly', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002f5', 'Whether you are using too many references', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002f5', 'Whether the borrow checker is inserting runtime checks', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002f6', 'Iterators and generics compile to the same code as the hand-written version', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002f6', 'Abstractions are free because Rust has no runtime at all', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002f6', 'The optimiser removes any code you do not call', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002f6', 'Traits are resolved by the JIT at first use', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002f7', 'Nothing - it enables five operations the compiler cannot verify', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002f7', 'The borrow checker, inside the block', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002f7', 'Lifetime checking for the whole function', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002f7', 'Bounds checking on every slice access in the crate', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002f8', 'Private by default, with pub and pub(crate) used deliberately', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002f8', 'Newtypes for domain values, which cost nothing and prevent mix-ups', 1, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002f8', 'Doc examples, because cargo test compiles and runs them', 1, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002f8', 'Everything marked pub, so the crate is easy to consume', 0, 4
  ) v;

